-- Aconchego – cardápio da noite (menu da casa + bebidas do Aiqfome), tamanhos e adicionais por tamanho
alter table public.produtos add column if not exists variacoes jsonb not null default '[]'::jsonb;
alter table public.adicionais add column if not exists preco_por_variacao jsonb;
update public.categorias set ativo = false where slug in ('petiscos','sobremesas');
update public.configuracoes set mostrar_precos = true where id = 1;
insert into public.categorias (slug,nome,turno,ordem,descricao,ativo)
select s,n,t::public.turno,o,d,true from jsonb_to_recordset('[{"s":"pizzas","n":"Pizzas","t":"noite","o":30,"d":"Pizzas do brotinho à família (12 pedaços). Meio a meio com qualquer sabor."},{"s":"pizzas-doces","n":"Pizzas doces","t":"noite","o":35,"d":null},{"s":"porcoes-na-chapa","n":"Porções","t":"noite","o":40,"d":"Porções na chapa para dividir: picanha, filé, chapa mista, tilápia, fritas e mais. Meia ou inteira."},{"s":"carne-na-chapa","n":"Carne na chapa","t":"noite","o":45,"d":"Filé, picanha, contra filé ou lombo na chapa, no peso. Acompanha farofa e vinagrete."},{"s":"guarnicoes","n":"Guarnições","t":"noite","o":48,"d":null},{"s":"sugestoes-da-casa","n":"Sugestões da casa","t":"noite","o":50,"d":null},{"s":"crepes","n":"Crepes","t":"noite","o":55,"d":null},{"s":"omeletes","n":"Omeletes","t":"noite","o":58,"d":null},{"s":"massas","n":"Massas","t":"noite","o":60,"d":null},{"s":"tabua-de-frios","n":"Tábua de frios","t":"noite","o":62,"d":null},{"s":"bebidas","n":"Bebidas","t":"ambos","o":70,"d":"Refrigerantes, água e suco, no almoço e à noite."}]'::jsonb) as x(s text,n text,t text,o int,d text)
on conflict (slug) do update set nome=excluded.nome, turno=excluded.turno, ordem=excluded.ordem, descricao=excluded.descricao, ativo=true;
insert into public.produtos (categoria_id,nome,slug,descricao,preco,variacoes,tags,meio_a_meio,destaque,ordem)
select c.id,x.n,x.s,x.d,x.p,coalesce(x.v,'[]'::jsonb),coalesce(array(select jsonb_array_elements_text(x.t)),'{}'),coalesce(x.m,false),coalesce(x.x,false),coalesce(x.o,0)
