insert into public.adicionais (produto_id,nome,preco,preco_por_variacao,ordem)
select p.id,a.nome,8,'{"Brotinho":8,"Pequena (4 pedaços)":8,"Média (6 pedaços)":8,"Grande (8 pedaços)":10,"Gigante (10 pedaços)":10,"Família (12 pedaços)":10}'::jsonb,a.ordem
from public.produtos p join public.categorias c on c.id=p.categoria_id
cross join (values ('Borda de Catupiry',0),('Borda de Cheddar Catupiry',1),('Cheddar',2),('Palmito',3),('Bacon',4),('Calabresa',5)) as a(nome,ordem)
where c.slug in ('pizzas','pizzas-doces') and not exists (select 1 from public.adicionais z where z.produto_id=p.id and z.nome=a.nome);
update public.faq set resposta = 'Sim. O Aconchego é choperia no almoço e à noite: chopp gelado com o almoço e, à noite, com pizza e porções no Bar Aconchego.' where pergunta = 'Tem chopp gelado?';
insert into public.faq (pergunta, resposta, ordem) select 'O Aconchego funciona como bar à noite?', 'Sim. De terça a domingo, das 18h à meia-noite, o Bar Aconchego serve chopp, porções na chapa, pizzas e crepes no centro de Pompéu – MG.', 105 where not exists (select 1 from public.faq where pergunta = 'O Aconchego funciona como bar à noite?');
select (select count(*) from public.produtos) produtos, (select count(*) from public.adicionais) adicionais, (select count(*) from public.categorias where ativo) categorias;
